<script>
const canvas=document.getElementById('graphCanvas'),ctx=canvas.getContext('2d');
const graph=document.getElementById('graphView'), expr=document.getElementById('expression');
const keyboard=document.getElementById('keyboard'), keyArea=document.getElementById('keyArea');
let expression='', activeCat='num', graphMode=true;

function resize(){canvas.width=graph.clientWidth*devicePixelRatio;canvas.height=graph.clientHeight*devicePixelRatio;draw()}
function draw(){
 const w=canvas.width/devicePixelRatio,h=canvas.height/devicePixelRatio,d=devicePixelRatio;
 ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);
 let scale=75, ox=w/2, oy=h*.54;
 ctx.strokeStyle='#eeeeee';ctx.lineWidth=1;
 for(let x=ox%scale;x<w;x+=scale){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}
 for(let y=oy%scale;y<h;y+=scale){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
 ctx.strokeStyle='#c8c8c8';ctx.lineWidth=1.3;
 for(let x=ox%scale;x<w;x+=scale){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}
 for(let y=oy%scale;y<h;y+=scale){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
 ctx.strokeStyle='#444';ctx.lineWidth=1.5;
 ctx.beginPath();ctx.moveTo(ox,0);ctx.lineTo(ox,h);ctx.stroke();
 ctx.beginPath();ctx.moveTo(0,oy);ctx.lineTo(w,oy);ctx.stroke();
 ctx.fillStyle='#444';ctx.font='16px Arial';
 for(let i=-5;i<=5;i++){if(i!==0){ctx.fillText(i,ox+i*scale-6,oy+20);ctx.fillText(i,ox-23,oy-i*scale+5)}}
 ctx.fillText('0',ox-17,oy+22);
 if(expression && expression.replace(/\s/g,'').includes('sin(x')){
   ctx.strokeStyle='#399b82';ctx.lineWidth=3;ctx.beginPath();
   for(let px=-10;px<=w+10;px+=2){
    let x=(px-ox)/scale, y=Math.sin(x), py=oy-y*scale;
    if(px===-10)ctx.moveTo(px,py);else ctx.lineTo(px,py);
   }ctx.stroke();
   [-3.14,-1.57,0,1.57,3.14].forEach(x=>{let px=ox+x*scale,py=oy-Math.sin(x)*scale;ctx.fillStyle='#777';ctx.beginPath();ctx.arc(px,py,7,0,Math.PI*2);ctx.fill()})
 }
}
function setView(view){
 document.getElementById('graphView').style.display=view==='graph'?'block':'none';
 document.getElementById('toolsView').style.display=view==='tools'?'flex':'none';
 document.getElementById('tableView').style.display=view==='table'?'block':'none';
 document.getElementById('sheetView').style.display=view==='sheet'?'block':'none';
 document.getElementById('inputPanel').style.display=view==='graph'?'block':'none';
 document.getElementById('brand').style.display=view==='graph'?'flex':'none';
 document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
 graphMode=view==='graph'; if(graphMode)resize();
}
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view));
expr.onclick=()=>{if(graphMode){expr.classList.add('active');keyboard.classList.add('show');renderKeys()}};
document.getElementById('closeKeys').onclick=()=>{keyboard.classList.remove('show');expr.classList.remove('active')};
document.querySelectorAll('.cat').forEach(c=>c.onclick=()=>{activeCat=c.dataset.cat;document.querySelectorAll('.cat').forEach(x=>x.classList.toggle('selected',x===c));renderKeys()});
function add(v){expression+=v;expr.textContent=expression||'Input...';draw()}
function renderKeys(){
 let rows=[];
 if(activeCat==='num')rows=[
 ['x','y','π','e','7','8','9','×','÷'],
 ['□²','□ᵃ','√□','▥','4','5','6','+','−'],
 ['<','>','▱','▦','1','2','3','=','⌫'],
 ['ans',',','(',')','0','.','‹','›','↵']];
 if(activeCat==='func')rows=[
 ['sin','cos','tan','%','!','$','°'],['sin⁻¹','cos⁻¹','tan⁻¹','{','}','≤','≥'],['ln','log₁₀','log','d⁄dx','∫','i','⌫'],['eᵃ','10ᵃ','√□','□...','‹','›','↵']];
 if(activeCat==='alpha')rows=[['q','w','e','r','t','y','u','i','o','p'],['a','s','d','f','g','h','j','k','l'],['⌃','z','x','c','v','b','n','m','⌫'],['αβγ',',','(',')',' ','‹','›','↵']];
 if(activeCat==='sym')rows=[['+','−','×','÷','=','≠','≈'],['<','>','≤','≥','{','}','⌫'],['∑','∫','√','π','∞','°','↵']];
 keyArea.innerHTML='<div class="keys '+(activeCat==='alpha'?'alpha':'')+'">'+rows.flat().map(k=>`<button class="key btn ${['⌫','↵','‹','›'].includes(k)?'dark':''}" data-key="${k}">${k}</button>`).join('')+'</div>';
 keyArea.querySelectorAll('.key').forEach(k=>k.onclick=()=>{let v=k.dataset.key;if(v==='sin')add('sin(');else if(v==='ln')add('ln(');else if(v==='⌫')expression=expression.slice(0,-1),expr.textContent=expression||'Input...',draw();else if(v==='↵'){}else if(v==='x')add('x');else if(!['‹','›','⌃'].includes(v))add(v);});
}
window.addEventListener('resize',resize);resize();renderKeys();
</script>
